import{K as r,a as i,c as l,b as a,k as n,q as d,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Word 分节、页眉页脚与页码","description":"用分节符实现封面无页码、目录罗马数字、正文从 1 编号，以及单独横向页面、不同页眉和异常空白页排查。","frontmatter":{"title":"Word 分节、页眉页脚与页码","description":"用分节符实现封面无页码、目录罗马数字、正文从 1 编号，以及单独横向页面、不同页眉和异常空白页排查。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Word 文档排版","summary":"用分节符实现封面无页码、目录罗马数字、正文从 1 编号，以及单独横向页面、不同页眉和异常空白页排查。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Word 样式、多级编号与自动目录","link":"/tools/office/word/styles"},"next":{"text":"Word 表格制作与跨页排版","link":"/tools/office/word/tables"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Word 样式、多级编号与自动目录","link":"/tools/office/word/styles"},"next":{"text":"Word 表格制作与跨页排版","link":"/tools/office/word/tables"}},"headers":[],"relativePath":"tools/office/word/sections.md","filePath":"tools/office/word/sections.md"}'),c={name:"tools/office/word/sections.md"},k=Object.assign(c,{setup(h){const t={path:"/tools/office/word/sections",app:"Word",title:"封面无页码，目录用罗马数字",steps:[{tab:"布局",command:"分隔符",setting:"分节符：下一页；位置：封面末尾、目录末尾",anchor:"walkthrough-1"},{tab:"页眉和页脚",command:"链接到前一节",setting:"第 2 节页脚：关闭；第 3 节页脚：关闭",anchor:"walkthrough-2"},{tab:"页眉和页脚",command:"页码",setting:"第 2 节：i 起；第 3 节：1 起",anchor:"walkthrough-3"}]};return(p,e)=>{const o=r("OfficeGuide");return i(),l("div",null,[e[0]||(e[0]=a("h1",{id:"word-分节、页眉页脚与页码",tabindex:"-1"},[n("Word 分节、页眉页脚与页码 "),a("a",{class:"header-anchor",href:"#word-分节、页眉页脚与页码","aria-label":'Permalink to "Word 分节、页眉页脚与页码"'},"​")],-1)),e[1]||(e[1]=a("p",null,"分页决定文字从哪里开始新的一页；分节决定页面设置从哪里开始独立。需要正文从 1 编号、某一页横向或不同章节页眉时，通常要使用分节。",-1)),d(o,{guide:t}),e[2]||(e[2]=s('<h2 id="plan" tabindex="-1">先画出节的结构 <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;先画出节的结构 {#plan}&quot;">​</a></h2><p>本篇建立三个节：第一节封面不显示页码，第二节目录使用 <code>i、ii</code>，第三节正文使用 <code>1、2、3</code>。先输入封面、目录占位和至少三页正文，打开编辑标记，让分隔符可见。</p><p>在封面末尾选择“布局 → 分隔符 → 分节符 → 下一页”；在目录末尾再插入一个“下一页”分节符。若此前已经有分页符，检查是否形成重复换页，避免多出空白页。</p><table tabindex="0"><thead><tr><th>分隔符</th><th>常见用途</th></tr></thead><tbody><tr><td>分页符</td><td>仅强制下一页开始</td></tr><tr><td>下一页分节符</td><td>新章节、新页码体系</td></tr><tr><td>连续分节符</td><td>同页分栏等局部布局变化</td></tr><tr><td>奇数页/偶数页分节符</td><td>书册章节从指定单双页开始，可能产生空白页</td></tr></tbody></table><h2 id="numbers" tabindex="-1">设置目录与正文页码 <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;设置目录与正文页码 {#numbers}&quot;">​</a></h2><ol><li>双击目录页页脚，确认状态显示为第二节。</li><li>在“页眉和页脚”选项卡中关闭页脚的“链接到前一节”。链接是针对当前页眉或页脚类型分别控制的，关闭页脚链接不会自动关闭页眉链接。</li><li>插入页码，打开“设置页码格式”，选择罗马数字并设置起始页码为 <code>i</code>。</li><li>到正文第一页页脚，关闭第三节页脚的“链接到前一节”。</li><li>设置阿拉伯数字格式，起始页码为 <code>1</code>，而非续前节。</li><li>回到封面检查没有页码；需要删除封面页码时先确认后面节已经解除对应链接。</li></ol><p>仅要求同一节第一页不显示页码时可以考虑“首页不同”；但它只是使用独立的首页页眉页脚，不会自动把第二页的页码改为 1。需要不同编号体系时分节更清楚。</p><h2 id="headers" tabindex="-1">页眉、奇偶页与链接关系 <a class="header-anchor" href="#headers" aria-label="Permalink to &quot;页眉、奇偶页与链接关系 {#headers}&quot;">​</a></h2><p>每节可能有普通页眉页脚、首页页眉页脚，以及启用“奇偶页不同”后的奇偶页类型。看见“与上一节相同”时，表示当前类型仍然链接前节。修改页眉前确认正在编辑哪一节、哪一种类型。</p><p>若整篇页眉应一致，保留链接有助于统一维护；若各章名称不同，则在相应节解除链接后输入。不要为每一页都创建一个节，除非页面设置确实不同；大量无必要的节会增加排错成本。</p><h2 id="landscape" tabindex="-1">让宽表格单独横向 <a class="header-anchor" href="#landscape" aria-label="Permalink to &quot;让宽表格单独横向 {#landscape}&quot;">​</a></h2><p>在宽表格前后分别插入“下一页”分节符，将光标放在表格所在节，选择“布局 → 方向 → 横向”。检查页面设置的应用范围为本节；后面节应恢复纵向。若后文也横向，通常是缺少表格后的分节符或应用范围选错。</p><p>横向页仍可沿用连续页码：在该节页码格式中选择续前节，再检查表格后那一节也续前节。页眉页脚位置可能需要根据方向微调，交付前必须逐页预览。</p><h2 id="problems" tabindex="-1">排错顺序 <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;排错顺序 {#problems}&quot;">​</a></h2><p>页码突然从 1 开始：查看该节“起始页码/续前节”。修改正文页脚影响封面：检查对应类型是否仍链接。出现删不掉的空白页：先看奇偶页分节符、重复分页以及段落分页设置。删除分节符会合并节并可能改变前面内容的页面格式，因此先在副本中试验。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>制作封面一页、目录一页、正文三页，并将正文中间的一张表放在独立横向页。封面无页码，目录显示 <code>i</code>，正文从 1 连续编号。导出 PDF 后逐页检查方向与页码，更新目录核对其页码是否指向实际正文。</p><p>参考入口：<a href="https://support.microsoft.com/en-us/word/" target="_blank" rel="noopener noreferrer">Word 帮助与学习</a>，查阅分节符和不同节页码相关说明。</p><h2 id="walkthrough" tabindex="-1">图示跟做：封面无页码，目录用罗马数字 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：封面无页码，目录用罗马数字 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先建立三个独立的节 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先建立三个独立的节 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：布局 → 分隔符。</strong></p><p>在练习副本中输入封面、目录占位和正文。把光标放到封面最后一个段落之后，选择“布局 → 分隔符 → 分节符 → 下一页”；在目录结束处再做一次。打开编辑标记，确认看见两个分节符而非仅两个分页符。已有分页符时检查是否造成重复换页。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：先断开页脚链接再改编号 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：先断开页脚链接再改编号 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：页眉和页脚 → 链接到前一节。</strong></p><p>双击目录页下方进入页脚，确认界面显示第 2 节，关闭“链接到前一节”。再到正文第一页，对第 3 节页脚做同样操作。页眉与页脚分别控制；如果启用首页不同或奇偶页不同，还要检查对应类型的链接，不要误改其他节。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：分别设置格式并逐页验收 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：分别设置格式并逐页验收 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：页眉和页脚 → 页码。</strong></p><p>在第 2 节插入页码，进入设置页码格式，选 i、ii、iii 并从 i 开始。在第 3 节选 1、2、3 并从 1 开始。确认后续节已断开对应页脚链接，再检查或删除封面页码。导出 PDF，核对封面为空、目录为 i、正文从 1 连续，不能只检查当前编辑页。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>“链接到前一节”灰色时先看当前是不是第 1 节、是否真的插入了分节符；正文从 2 开始时，检查起始页码和首页不同。不要靠手输数字覆盖自动页码。</p><p>图示操作参考：<a href="https://support.microsoft.com/zh-cn/word/link-to-previous" target="_blank" rel="noopener noreferrer">微软官方：分节与链接到前一节</a>。核对日期：2026-11-02；界面示意与练习案例为本站独立编写。</p>',32))])}}});export{u as __pageData,k as default};
